package com.github.tartaricacid.touhoulittlemaid.client.sound;
import cpw.mods.fml.relauncher.ReflectionHelper;import net.minecraft.client.Minecraft;import net.minecraft.client.audio.SoundHandler;import net.minecraft.client.audio.SoundManager;import net.minecraft.entity.Entity;import paulscode.sound.SoundSystem;import paulscode.sound.SoundSystemConfig;import paulscode.sound.codecs.CodecWav;import java.io.File;import java.io.FileOutputStream;import java.lang.reflect.Field;import java.net.URL;import java.security.MessageDigest;
/** Writes bounded server audio into the client cache and plays it positionally. */
public final class DynamicTtsPlayer{private DynamicTtsPlayer(){}public static void play(int entityId,byte[] audio){if(audio==null||audio.length<4)return;try{Minecraft mc=Minecraft.getMinecraft();Entity e=mc.theWorld==null?null:mc.theWorld.getEntityByID(entityId);if(e==null)return;SoundSystemConfig.setCodec("wav",CodecWav.class);String hash=hex(MessageDigest.getInstance("SHA-1").digest(audio));File dir=new File(mc.mcDataDir,"tlm_tts_cache");if(!dir.exists())dir.mkdirs();File file=new File(dir,hash+".wav");if(!file.exists()){FileOutputStream out=new FileOutputStream(file);out.write(audio);out.close();}SoundHandler handler=mc.getSoundHandler();Field managerField=ReflectionHelper.findField(SoundHandler.class,"sndManager","field_147694_f");SoundManager manager=(SoundManager)managerField.get(handler);Field systemField=ReflectionHelper.findField(SoundManager.class,"sndSystem","field_148620_e");SoundSystem system=(SoundSystem)systemField.get(manager);String source="tlm_tts_"+entityId;URL url=file.toURI().toURL();system.stop(source);system.newStreamingSource(false,source,url,file.getName(),false,(float)e.posX,(float)e.posY,(float)e.posZ,SoundSystemConfig.ATTENUATION_LINEAR,24);system.play(source);prune(dir);}catch(Exception ignored){}}
private static void prune(File dir){File[] files=dir.listFiles();if(files==null||files.length<=32)return;java.util.Arrays.sort(files,new java.util.Comparator<File>(){public int compare(File a,File b){return Long.compare(a.lastModified(),b.lastModified());}});for(int i=0;i<files.length-32;i++)files[i].delete();}private static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format("%02x",b&255));return s.toString();}}
